CREATE FUNCTION cmd_reject_steward_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Steward service receipts are immutable'; END $$;
CREATE TRIGGER cmd_steward_service_receipt_immutable BEFORE UPDATE OR DELETE ON cmd_steward_service_receipt FOR EACH ROW EXECUTE FUNCTION cmd_reject_steward_mutation();
CREATE FUNCTION cmd_validate_steward_receipt() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE task cmd_actor_task_receipt%ROWTYPE; BEGIN SELECT * INTO STRICT task FROM cmd_actor_task_receipt WHERE command_id=NEW.task_command_id; IF task.actor_id<>NEW.steward_actor_id OR task.skill_rule_id<>(SELECT skill_rule_id FROM rule_steward_mechanic WHERE rule_id=NEW.service_rule_id) OR task.check_total<>NEW.check_total OR task.effect<>NEW.effect OR task.succeeded<>NEW.succeeded OR NOT EXISTS(SELECT 1 FROM journey_participant WHERE journey_id=NEW.journey_id AND campaign_id=NEW.campaign_id AND actor_id=NEW.steward_actor_id AND participant_role='crew' AND commitment_status IN('planned','committed')) OR NOT EXISTS(SELECT 1 FROM journey_passage WHERE journey_id=NEW.journey_id AND campaign_id=NEW.campaign_id AND actor_id=NEW.passenger_actor_id AND passage_class='high' AND passage_status IN('booked','boarded')) THEN RAISE EXCEPTION 'Steward receipt does not match its task, crew assignment, or high passage'; END IF; RETURN NEW; END $$;
CREATE CONSTRAINT TRIGGER cmd_steward_service_receipt_valid AFTER INSERT ON cmd_steward_service_receipt DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION cmd_validate_steward_receipt();
